    {
      "id": "TEST-003",
      "class": "security",
      "scope": "Service Agent and unauthorised-user privilege matrix.",
      "expected": "The agent can create and read owned requests but cannot update, delete, assign, or share; the unauthorised user cannot access the app or table.",
      "evidence_required": "Role definition inspection, assignment readback, and non-admin runtime results.",
      "status": "planned"
    },
    {
      "id": "TEST-004",
      "class": "reliability",
      "scope": "Double-save, retry with the same Submission ID, and duplicate alternate-key behavior.",
      "expected": "At most one row exists and feedback provides safe reconciliation guidance.",
      "evidence_required": "Automated rapid-action test, duplicate-key result, and row-count reconciliation.",
      "status": "planned"
    },
    {
      "id": "TEST-005",
      "class": "reliability",
      "scope": "Concurrent-change and stale-submission contract using two versions and the request ID, action type, and expected-version idempotency key.",
      "expected": "A stale or repeated write is rejected without data loss and produces reload-and-reconcile guidance.",
      "evidence_required": "Contract-level test now and runtime two-session evidence before any update or acknowledgement path is released.",
      "status": "planned"
    },
    {
      "id": "TEST-006",
      "class": "accessibility",
      "scope": "Keyboard order, focus, labels, validation summary, save-status announcement, narrow layout, and long content.",
      "expected": "The primary journey and all feedback remain perceivable and operable.",
      "evidence_required": "Accessibility checklist and assistive-technology runtime captures.",
      "status": "planned"
    },
    {
      "id": "TEST-007",
      "class": "performance",
      "scope": "Create-form load and save responsiveness under an agreed target test baseline.",
      "expected": "No duplicate action becomes possible during loading or save and measured timings meet the target baseline approved before testing.",
      "evidence_required": "Sanitized timing results, test conditions, and baseline approval.",
      "status": "planned"
    },
    {
      "id": "TEST-008",
      "class": "alm",
      "scope": "Solution ownership, unmanaged-source validation, managed export, component inventory, dependencies, version, and checksum.",
      "expected": "All slice components are solution-owned and the managed artifact is deterministic and complete.",
      "evidence_required": "Solution validation output, unpacked-source review, inventory, dependency report, version, and checksum.",
      "status": "planned"
    },
    {
      "id": "TEST-009",
      "class": "deployment",
      "scope": "Managed import, publish, alternate-key activation, app sharing, role assignment, and configuration readback.",
      "expected": "The target configuration matches the approved package and prerequisites without unmanaged target edits.",
      "evidence_required": "Observed import history, publish result, key status, app and role readback, and artifact checksum.",
      "status": "not-run"
    },
    {
      "id": "TEST-010",
      "class": "rollback",
      "scope": "Access withdrawal and managed solution removal or approved version rollback with synthetic data handling.",
      "expected": "The app can be withdrawn safely and rollback does not silently destroy data.",
      "evidence_required": "Rehearsed rollback record in a non-production target, data disposition record, and post-rollback readback.",
      "status": "planned"
    }
  ],
  "deployment": {
    "authorization_status": "not-requested",
    "target_zone": "organisational-microsoft",
    "environments": [
      "Authorised Dataverse development environment",
      "Authorised Dataverse test environment",
      "Approved organisational target environment"
    ],
